-- Clean bootstrap 007: automation rule schema only.
CREATE TABLE IF NOT EXISTS public.automation_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,description text,trigger_type text NOT NULL,priority integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.rule_conditions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid NOT NULL REFERENCES public.automation_rules(id) ON DELETE CASCADE,field text NOT NULL,operator text NOT NULL,value jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.rule_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid NOT NULL REFERENCES public.automation_rules(id) ON DELETE CASCADE,action_type text NOT NULL,parameters jsonb NOT NULL DEFAULT '{}'::jsonb,execution_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.rule_execution_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid REFERENCES public.automation_rules(id) ON DELETE SET NULL,affected_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,success boolean NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,executed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.user_blocking_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,reason text NOT NULL,blocked_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,blocked_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.escalation_configurations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,severity text NOT NULL,delay_minutes integer NOT NULL DEFAULT 0,primary_admin_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,channels text[] NOT NULL DEFAULT ARRAY['email'],is_active boolean NOT NULL DEFAULT true);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['automation_rules','rule_conditions','rule_actions','rule_execution_history','user_blocking_records','escalation_configurations'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS automation_admin ON public.%I',t); EXECUTE format('CREATE POLICY automation_admin ON public.%I FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin())',t); END LOOP; END $$;
